Here's a complete checkout page implementation with React + TypeScript and plain CSS.

**CheckoutPage.tsx**

```tsx
import React, { useMemo, useState } from 'react';
import './CheckoutPage.css';

export interface CartItem {
  id: string;
  name: string;
  imageUrl: string;
  price: number;
  quantity: number;
}

export interface DeliveryAddress {
  fullName: string;
  street: string;
  city: string;
  postalCode: string;
  country: string;
  phone: string;
}

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

interface CheckoutPageProps {
  items: CartItem[];
  onBack: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
  shippingCost?: number;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

const formatPrice = (value: number): string => `$${value.toFixed(2)}`;

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = 'Full name is required';
  if (!address.street.trim()) errors.street = 'Street address is required';
  if (!address.city.trim()) errors.city = 'City is required';
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required';
  } else if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = 'Enter a valid postal code';
  }
  if (!address.country.trim()) errors.country = 'Country is required';
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required';
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }

  return errors;
}

export default function CheckoutPage({
  items,
  onBack,
  onPay,
  shippingCost = 4.99,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = subtotal + (items.length > 0 ? shippingCost : 0);
  const isCartEmpty = items.length === 0;

  const handleChange =
    (field: keyof DeliveryAddress) =>
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const value = e.target.value;
      setAddress((prev) => ({ ...prev, [field]: value }));
      setErrors((prev) => ({ ...prev, [field]: undefined }));
    };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setPayError(null);

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0 || isCartEmpty) {
      return;
    }

    setIsSubmitting(true);
    try {
      await onPay(address);
    } catch (err) {
      setPayError(
        err instanceof Error ? err.message : 'Payment failed. Please try again.'
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBack}
          aria-label="Back to cart"
        >
          &larr; Back to cart
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="checkout-section" aria-labelledby="order-summary-heading">
          <h2 id="order-summary-heading" className="section-heading">
            Order Summary
          </h2>

          {isCartEmpty ? (
            <p className="empty-cart-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <img
                    src={item.imageUrl}
                    alt={item.name}
                    className="cart-item-image"
                  />
                  <div className="cart-item-info">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="totals">
            <div className="totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="totals-row">
              <span>Shipping</span>
              <span>{isCartEmpty ? formatPrice(0) : formatPrice(shippingCost)}</span>
            </div>
            <div className="totals-row totals-row-grand">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </section>

        <section className="checkout-section" aria-labelledby="address-heading">
          <h2 id="address-heading" className="section-heading">
            Delivery Address
          </h2>

          <form className="address-form" onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                autoComplete="name"
                value={address.fullName}
                onChange={handleChange('fullName')}
                aria-invalid={!!errors.fullName}
                aria-describedby={errors.fullName ? 'fullName-error' : undefined}
              />
              {errors.fullName && (
                <span id="fullName-error" className="field-error">
                  {errors.fullName}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                autoComplete="street-address"
                value={address.street}
                onChange={handleChange('street')}
                aria-invalid={!!errors.street}
                aria-describedby={errors.street ? 'street-error' : undefined}
              />
              {errors.street && (
                <span id="street-error" className="field-error">
                  {errors.street}
                </span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  autoComplete="address-level2"
                  value={address.city}
                  onChange={handleChange('city')}
                  aria-invalid={!!errors.city}
                  aria-describedby={errors.city ? 'city-error' : undefined}
                />
                {errors.city && (
                  <span id="city-error" className="field-error">
                    {errors.city}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  autoComplete="postal-code"
                  value={address.postalCode}
                  onChange={handleChange('postalCode')}
                  aria-invalid={!!errors.postalCode}
                  aria-describedby={errors.postalCode ? 'postalCode-error' : undefined}
                />
                {errors.postalCode && (
                  <span id="postalCode-error" className="field-error">
                    {errors.postalCode}
                  </span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                autoComplete="country-name"
                value={address.country}
                onChange={handleChange('country')}
                aria-invalid={!!errors.country}
                aria-describedby={errors.country ? 'country-error' : undefined}
              />
              {errors.country && (
                <span id="country-error" className="field-error">
                  {errors.country}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                autoComplete="tel"
                value={address.phone}
                onChange={handleChange('phone')}
                aria-invalid={!!errors.phone}
                aria-describedby={errors.phone ? 'phone-error' : undefined}
              />
              {errors.phone && (
                <span id="phone-error" className="field-error">
                  {errors.phone}
                </span>
              )}
            </div>

            {payError && (
              <div className="pay-error" role="alert">
                {payError}
              </div>
            )}

            <div className="checkout-actions">
              <button
                type="button"
                className="secondary-button"
                onClick={onBack}
                disabled={isSubmitting}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="primary-button"
                disabled={isSubmitting || isCartEmpty}
              >
                {isSubmitting ? 'Processing…' : `Pay ${formatPrice(total)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

